import { ChangeEvent, useEffect, useMemo, useRef, useState } from "react";
import { analyzeAudioTonality, analyzeMidiPerformance, extractTopMelody, parseMidi, type MidiPerformanceMetrics, type PianoReport } from "./piano-analysis";
import { GlassButton } from "./components/GlassButton";
import { mapPlaybackPosition, parseMarkerTimestamp } from "./piano-markers";
import { loadPianoHistory, persistPianoHistory, type SavedPianoVersion } from "./piano-history";
import { analyzeCompositionAudio, compareCompositions, decodeAudioFile, type CompositionAnalysis, type CompositionComparison } from "./audio-composition";
import { ReferenceLibraryPanel } from "./ReferenceLibraryPanel";
import { transcribePianoAudio, type PianoTranscription } from "./piano-transcription";
import { assessReferenceProfile, evaluateDemoAgainstProfile, loadReferenceProfile, profileIsReady, REFERENCE_PROFILE_STORAGE_KEY, saveReferenceProfile, type ProfileEvaluation, type ReferenceLibraryProfile } from "./reference-profile";

const AUDIO_ACCEPT = ".wav,.flac,.mp3,.m4a,.aac,.ogg,.opus";
const AUDIO_EXTENSIONS = new Set(AUDIO_ACCEPT.split(",").map(extension => extension.slice(1)));
const MIDI_EXTENSIONS = new Set(["mid", "midi"]);
const MAXIMUM_AUDIO_SIZE = 300 * 1024 * 1024;
const MAXIMUM_MIDI_SIZE = 10 * 1024 * 1024;
const CHECKS = ["Cảm giác thư giãn, không thu hút quá nhiều chú ý", "Giai điệu tự nhiên, không có nốt gượng", "Đủ khoảng trống giữa các câu", "Motif dễ nhận ra nhưng không lặp khó chịu", "Tay trái và hợp âm đơn giản", "Hướng đi giai điệu rõ ràng", "Phù hợp với mục tiêu / hồ sơ tham chiếu"];
const CHECKS_EN = ["Calm and unobtrusive", "Natural melody without awkward notes", "Enough breathing room between phrases", "Recognizable motif without annoying repetition", "Simple left hand and harmony", "Clear melodic direction", "Fit for the target / reference profile"];
const time = (value: number) => `${Math.floor(value / 60)}:${String(Math.floor(value % 60)).padStart(2, "0")}`;
async function copyPianoFeedback(text: string) {
  if (navigator.clipboard?.writeText) { await navigator.clipboard.writeText(text); return; }
  const textarea = document.createElement("textarea");
  textarea.value = text;
  textarea.setAttribute("readonly", "");
  textarea.style.position = "fixed";
  textarea.style.opacity = "0";
  document.body.appendChild(textarea);
  textarea.select();
  const copied = document.execCommand("copy");
  textarea.remove();
  if (!copied) throw new Error("Trình duyệt không cho phép sao chép tự động.");
}
type AudioResult = Awaited<ReturnType<typeof analyzeAudioTonality>>;
type Marker = { id: string; time: number; text: string };

export function PianoMode() {
  const [demo, setDemo] = useState<File>(); const [reference, setReference] = useState<File>(); const [demoMidi, setDemoMidi] = useState<File>(); const [referenceMidi, setReferenceMidi] = useState<File>();
  const [audioResult, setAudioResult] = useState<AudioResult>(); const [composition, setComposition] = useState<CompositionAnalysis>(); const [referenceComposition, setReferenceComposition] = useState<CompositionAnalysis>(); const [demoReport, setDemoReport] = useState<PianoReport>(); const [referenceReport, setReferenceReport] = useState<PianoReport>(); const [transcription, setTranscription] = useState<PianoTranscription>(); const [referenceTranscription, setReferenceTranscription] = useState<PianoTranscription>();
  const [profile, setProfile] = useState<ReferenceLibraryProfile | undefined>(() => loadReferenceProfile());
  const profileHealth = assessReferenceProfile(profile);
  const [busy, setBusy] = useState(false); const [libraryBusy, setLibraryBusy] = useState(false); const [error, setError] = useState(""); const [aiProgress, setAiProgress] = useState(0); const [aiLabel, setAiLabel] = useState("Demo"); const [transcriptionWarning, setTranscriptionWarning] = useState("");
  const analysisRun = useRef(0);
  useEffect(() => () => { analysisRun.current += 1; }, []);
  const resetResults = () => { setAudioResult(undefined); setComposition(undefined); setReferenceComposition(undefined); setDemoReport(undefined); setReferenceReport(undefined); setTranscription(undefined); setReferenceTranscription(undefined); setTranscriptionWarning(""); };
  const updateProfile = (next?: ReferenceLibraryProfile) => {
    setProfile(next);
    try {
      if (next) saveReferenceProfile(next); else localStorage.removeItem(REFERENCE_PROFILE_STORAGE_KEY);
    } catch {
      setError("Trình duyệt không thể lưu hồ sơ trên thiết bị. Hãy xuất JSON để tránh mất dữ liệu.");
    }
  };
  const choose = (setter: (file?: File) => void, kind: "audio" | "midi") => (event: ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    event.target.value = "";
    if (!file) return;
    const extension = file.name.split(".").pop()?.toLowerCase() ?? "";
    const supported = kind === "audio" ? AUDIO_EXTENSIONS.has(extension) : MIDI_EXTENSIONS.has(extension);
    const maximumSize = kind === "audio" ? MAXIMUM_AUDIO_SIZE : MAXIMUM_MIDI_SIZE;
    if (!supported) { setError(kind === "audio" ? "Định dạng audio không được hỗ trợ." : "Tệp phải có định dạng .mid hoặc .midi."); return; }
    if (file.size > maximumSize) { setError(`Tệp vượt giới hạn ${kind === "audio" ? "300 MB" : "10 MB"}.`); return; }
    analysisRun.current += 1;
    setBusy(false);
    setter(file);
    resetResults();
    setError("");
  };
  const clearFile = (setter: (file?: File) => void) => {
    analysisRun.current += 1;
    setBusy(false);
    setter(undefined);
    resetResults();
    setError("");
  };
  const analyze = async () => {
    if (!demo) return;
    const run = ++analysisRun.current;
    setBusy(true); setError(""); setTranscriptionWarning(""); setAiProgress(0);
    try {
      const [demoBuffer, referenceBuffer, midi, refMidi] = await Promise.all([
        decodeAudioFile(demo),
        reference ? decodeAudioFile(reference) : undefined,
        demoMidi ? demoMidi.arrayBuffer().then(parseMidi) : undefined,
        referenceMidi ? referenceMidi.arrayBuffer().then(parseMidi) : undefined,
      ]);
      const [audio, compositionResult, referenceResult] = await Promise.all([
        analyzeAudioTonality(demo, demoBuffer),
        analyzeCompositionAudio(demo, demoBuffer),
        reference && referenceBuffer ? analyzeCompositionAudio(reference, referenceBuffer) : undefined,
      ]);
      const aiWarnings: string[] = [];
      let aiTranscription: PianoTranscription | undefined;
      let aiReferenceTranscription: PianoTranscription | undefined;
      try { setAiLabel("Demo"); aiTranscription = await transcribePianoAudio(demo, progress => { if (analysisRun.current === run) setAiProgress(reference ? progress * .5 : progress); }, demoBuffer); }
      catch { aiWarnings.push("AI không chép được nốt Demo; báo cáo vẫn dùng các đặc trưng audio."); }
      if (reference && referenceBuffer && analysisRun.current === run) {
        try { setAiLabel("Reference"); aiReferenceTranscription = await transcribePianoAudio(reference, progress => { if (analysisRun.current === run) setAiProgress(50 + progress * .5); }, referenceBuffer); }
        catch { aiWarnings.push("AI không chép được nốt Reference; so sánh vẫn dùng các đặc trưng audio."); }
      }
      if (analysisRun.current !== run) return;
      setAudioResult(audio); setComposition(compositionResult); setReferenceComposition(referenceResult); setDemoReport(midi); setReferenceReport(refMidi); setTranscription(aiTranscription); setReferenceTranscription(aiReferenceTranscription); setTranscriptionWarning(aiWarnings.join(" "));
    } catch (reason) {
      if (analysisRun.current === run) setError(reason instanceof Error ? reason.message : "Không thể phân tích tệp.");
    } finally {
      if (analysisRun.current === run) setBusy(false);
    }
  };
  if (audioResult && composition && demo) return <Review demo={demo} reference={reference} audioResult={audioResult} composition={composition} referenceComposition={referenceComposition} demoReport={demoReport} referenceReport={referenceReport} transcription={transcription} referenceTranscription={referenceTranscription} transcriptionWarning={transcriptionWarning} profile={profile} onBack={() => setAudioResult(undefined)} />;
  return <div className="content piano-upload"><section className="piano-hero"><p className="eyebrow">ZIRECT · ĐÁNH GIÁ SÁNG TÁC</p><h1>Piano Relaxing</h1><p>Phân tích giai điệu và cấu trúc ngay trong trình duyệt. Chỉ Audio Demo là bắt buộc; chế độ này không chấm mix, master, EQ hay loudness.</p></section>
    <ReferenceLibraryPanel profile={profile} onChange={updateProfile} onBusyChange={setLibraryBusy} />
    <h2 className="piano-section-title">Audio</h2><section className="piano-files piano-audio-files"><FileTile title="Audio Demo" detail="Bắt buộc" accept={AUDIO_ACCEPT} file={demo} onChange={choose(setDemo, "audio")} onClear={() => clearFile(setDemo)} required /><FileTile title="Audio Reference" detail="Không bắt buộc" accept={AUDIO_ACCEPT} file={reference} onChange={choose(setReference, "audio")} onClear={() => clearFile(setReference)} /></section>
    <section className="midi-supplement"><header><div><p className="eyebrow">BỔ SUNG MIDI</p><h2>Phân tích sâu hơn bằng MIDI</h2></div><span>Cả hai tệp đều không bắt buộc</span></header><div className="piano-files piano-midi-files"><FileTile title="Demo MIDI" detail="Tuỳ chọn · mở piano roll và chỉ số giai điệu" accept=".mid,.midi,audio/midi" file={demoMidi} onChange={choose(setDemoMidi, "midi")} onClear={() => clearFile(setDemoMidi)} /><FileTile title="Reference MIDI" detail="Tuỳ chọn · mở bảng so sánh trực tiếp" accept=".mid,.midi,audio/midi" file={referenceMidi} onChange={choose(setReferenceMidi, "midi")} onClear={() => clearFile(setReferenceMidi)} /></div></section>
    {error && <p className="analysis-error" role="alert">{error}</p>}{busy && <p className="ai-analysis-progress">{aiProgress > 0 ? `AI đang chép nốt ${aiLabel} · ${Math.round(aiProgress)}%` : "Đang phân tích audio và đối chiếu BPM…"}</p>}<GlassButton className="piano-analyze" size="lg" variant="primary" disabled={!demo || busy || libraryBusy} loading={busy} onClick={analyze}>{libraryBusy ? "Đang xây hồ sơ…" : busy ? "Đang phân tích…" : profileHealth.status === "ready" ? "Đánh giá theo hồ sơ →" : profileHealth.status === "limited" ? "Đánh giá theo hồ sơ giới hạn →" : "Bắt đầu đánh giá →"}</GlassButton>{busy && <button type="button" className="piano-cancel-analysis" onClick={() => { analysisRun.current += 1; setBusy(false); setError("Đã bỏ kết quả của tác vụ đang chạy."); }}>Bỏ tác vụ</button>}
  </div>;
}
function FileTile({ title, detail, accept, file, onChange, onClear, required }: { title: string; detail: string; accept: string; file?: File; onChange: (event: ChangeEvent<HTMLInputElement>) => void; onClear: () => void; required?: boolean }) { return <div className={`piano-file ${file ? "ready" : ""}`}><label><span className="piano-file-icon">{file ? "✓" : "+"}</span><b>{title}</b><small>{file?.name ?? detail}</small><em>{required ? "BẮT BUỘC" : "TUỲ CHỌN"}</em><input type="file" accept={accept} onChange={onChange} /></label>{file && <button type="button" className="piano-file-clear" onClick={onClear} aria-label={`Xoá ${title}`}>Xoá tệp</button>}</div>; }

function Review({ demo, reference, audioResult, composition, referenceComposition, demoReport, referenceReport, transcription, referenceTranscription, transcriptionWarning, profile, onBack }: { demo: File; reference?: File; audioResult: AudioResult; composition: CompositionAnalysis; referenceComposition?: CompositionAnalysis; demoReport?: PianoReport; referenceReport?: PianoReport; transcription?: PianoTranscription; referenceTranscription?: PianoTranscription; transcriptionWarning: string; profile?: ReferenceLibraryProfile; onBack: () => void }) {
  const demoUrl = useMemo(() => URL.createObjectURL(demo), [demo]); const referenceUrl = useMemo(() => reference ? URL.createObjectURL(reference) : "", [reference]);
  useEffect(() => () => { URL.revokeObjectURL(demoUrl); if (referenceUrl) URL.revokeObjectURL(referenceUrl); }, [demoUrl, referenceUrl]);
  const tracks = useMemo(() => [...new Set(demoReport?.notes.map(note => note.track ?? 0) ?? [])], [demoReport]); const [melodyTrack, setMelodyTrack] = useState(tracks.at(-1) ?? 0); const [leftTrack, setLeftTrack] = useState(tracks[0] ?? 0);
  const metrics = useMemo(() => demoReport ? analyzeMidiPerformance(demoReport, melodyTrack, leftTrack) : undefined, [demoReport, melodyTrack, leftTrack]); const referenceMetrics = useMemo(() => referenceReport ? analyzeMidiPerformance(referenceReport) : undefined, [referenceReport]);
  const [scores, setScores] = useState(Array(7).fill(null) as Array<number | null>); const checklistComplete = scores.every((score): score is number => score !== null); const arScore = checklistComplete ? scores.reduce((sum, score) => sum + score!, 0) : undefined;
  const player = useRef<HTMLAudioElement>(null); const [position, setPosition] = useState(0); const [audioDuration, setAudioDuration] = useState(audioResult.duration);
  const seekSequence = useRef(0); const [seekRequest, setSeekRequest] = useState<{ id: number; demoTime: number }>();
  const seek = (next: number) => { const target = Math.max(0, Math.min(audioDuration, next)); setPosition(target); setSeekRequest({ id: ++seekSequence.current, demoTime: target }); };
  const [demoConfirmedBpm,setDemoConfirmedBpm]=useState(composition.bpm); const [demoBpmConfirmed,setDemoBpmConfirmed]=useState(false); const [referenceConfirmedBpm,setReferenceConfirmedBpm]=useState(referenceComposition?.bpm ?? 0);
  const confirmedDemo=useMemo(()=>({...composition,bpm:demoConfirmedBpm}),[composition,demoConfirmedBpm]); const confirmedReference=useMemo(()=>referenceComposition?({...referenceComposition,bpm:referenceConfirmedBpm}):undefined,[referenceComposition,referenceConfirmedBpm]);
  const comparison = useMemo(() => confirmedReference ? compareCompositions(confirmedDemo, confirmedReference) : undefined, [confirmedDemo, confirmedReference]);
  const profileEvaluation = useMemo(() => profileIsReady(profile) ? evaluateDemoAgainstProfile(confirmedDemo, transcription, profile!) : undefined, [confirmedDemo, transcription, profile]);
  const [markers, setMarkers] = useState<Marker[]>([]); const [feedbackVi, setFeedbackVi] = useState(() => feedback("vi", metrics, comparison, undefined, profileEvaluation, [], scores)); const [feedbackEn, setFeedbackEn] = useState(() => feedback("en", metrics, comparison, undefined, profileEvaluation, [], scores));
  const updateDemoBpm=(bpm:number)=>{setDemoConfirmedBpm(bpm);setDemoBpmConfirmed(true)};
  const regenerateFeedback=()=>{const confirmed=demoBpmConfirmed?demoConfirmedBpm:undefined;setFeedbackVi(feedback("vi",metrics,comparison,confirmed,profileEvaluation,markers,scores));setFeedbackEn(feedback("en",metrics,comparison,confirmed,profileEvaluation,markers,scores))};
  const [history, setHistory] = useState<SavedPianoVersion[]>(() => loadPianoHistory(demo)); const [historyError, setHistoryError] = useState("");
  const save = () => { const next = [...history, { version: `V${Math.min(3, history.length + 1)}`, date: new Date().toLocaleDateString("vi-VN"), bpm: demoConfirmedBpm, activity: audioResult.activityPercent, notesPerMinute: metrics?.notesPerMinute, restPercent: metrics?.restPercent ?? audioResult.restPercent, range: metrics?.range, arScore }].slice(-3); try { persistPianoHistory(demo, next); setHistory(next); setHistoryError(""); } catch { setHistoryError("Không thể lưu lịch sử trên thiết bị. Trình duyệt có thể đang chặn bộ nhớ cục bộ."); } };
  return <div className="content piano-report"><header className="review-title"><div><p className="eyebrow">PIANO RELAXING · BÁO CÁO</p><h1>{demo.name}</h1></div><button onClick={onBack}>Đánh giá mới</button></header>
    <CompositionOverview title="Audio estimates · Demo" result={composition} confirmedBpm={demoConfirmedBpm} onConfirmedBpm={updateDemoBpm} />
    {profileEvaluation && profile && <ProfileEvaluationPanel profile={profile} evaluation={profileEvaluation} onSeek={seek} />}
    {transcription && <AiTranscriptionSection transcription={transcription} position={position} audioDuration={audioDuration} seek={seek} />}
    {transcription && referenceTranscription && <AiTranscriptionComparison demo={transcription} reference={referenceTranscription} />}
    {transcriptionWarning && <section className="audio-limit"><h2>AI chép nốt chưa khả dụng</h2><p>{transcriptionWarning}</p></section>}
    {referenceComposition && <CompositionOverview title="Audio estimates · Reference" result={referenceComposition} confirmedBpm={referenceConfirmedBpm} onConfirmedBpm={setReferenceConfirmedBpm} />}
    {comparison && <AudioComparison comparison={comparison} seek={(start, length) => { seek(start); }} />}
    {!demoReport ? <section className="audio-limit"><h2>Phân biệt dữ liệu audio và MIDI</h2><p>{transcription ? "AI đã ước lượng nốt và top-voice từ audio để so với hồ sơ. Kết quả có thể bỏ sót hoặc nhận nhầm nốt, nên không được xem là bản MIDI chính xác." : "Audio vẫn cho phép ước lượng nhịp độ, hoạt động và khoảng nghỉ. Tạo hồ sơ từ ít nhất 5 bài để bật AI top-voice; thêm Demo MIDI nếu cần nốt, hợp âm và vai trò tay trái chính xác hơn."}</p></section> : <MidiSection report={demoReport} metrics={metrics!} tracks={tracks} melodyTrack={melodyTrack} leftTrack={leftTrack} setMelodyTrack={setMelodyTrack} setLeftTrack={setLeftTrack} position={position} audioDuration={audioDuration} seek={seek} />}
    {metrics && referenceMetrics && <Comparison demo={metrics} reference={referenceMetrics} />}
    <ABPlayer demoUrl={demoUrl} referenceUrl={referenceUrl} demoAnalysis={composition} referenceAnalysis={referenceComposition} comparison={comparison} markers={markers} setMarkers={setMarkers} audio={player} position={position} setPosition={setPosition} setDuration={setAudioDuration} seekRequest={seekRequest} />
    <section className="ar-checklist"><header><div><h2>Checklist A&amp;R</h2><p>Điểm nghe chủ quan, tách biệt hoàn toàn khỏi dữ liệu kỹ thuật. Web không tự điền điểm.</p></div><strong>{arScore ?? "—"}<small>/35</small></strong></header>{CHECKS.map((label, index) => <label key={label}><span>{index + 1}. {label}</span><select value={scores[index] ?? ""} onChange={event => setScores(current => current.map((score, i) => i === index ? (event.target.value ? Number(event.target.value) : null) : score))}><option value="">Chưa chấm</option>{[1,2,3,4,5].map(score => <option key={score} value={score}>{score}</option>)}</select></label>)}</section>
    <section className="feedback-refresh"><div><h2>Tạo feedback từ đánh giá hiện tại</h2><p>Chỉ cập nhật khi bạn bấm nút, để không ghi đè phần đã sửa tay.</p></div><button onClick={regenerateFeedback}>Tạo lại feedback Việt/Anh</button></section><FeedbackEditor language="Tiếng Việt" value={feedbackVi} setValue={setFeedbackVi} /><FeedbackEditor language="English" value={feedbackEn} setValue={setFeedbackEn} />
    <section className="version-history"><header><div><h2>Lịch sử phiên bản</h2><p>Lưu tối đa V1, V2 và V3 trên thiết bị này.</p></div><button onClick={save} disabled={history.length >= 3}>Lưu phiên bản</button></header>{historyError && <p className="analysis-error" role="alert">{historyError}</p>}{history.length ? <table><thead><tr><th>Phiên bản</th><th>BPM</th><th>Hoạt động</th><th>Nốt/phút</th><th>Nghỉ</th><th>Range</th><th>A&amp;R</th></tr></thead><tbody>{history.map(row => <tr key={row.version}><td>{row.version}<small>{row.date}</small></td><td>{row.bpm}</td><td>{row.activity}%</td><td>{row.notesPerMinute ?? "—"}</td><td>{row.restPercent}%</td><td>{row.range ?? "—"}</td><td>{row.arScore === undefined ? "—" : `${row.arScore}/35`}</td></tr>)}</tbody></table> : <p>Chưa có phiên bản được lưu.</p>}</section>
  </div>;
}
function AudioOverview({ result }: { result: AudioResult }) { return <section className="audio-overview"><div className="audio-facts"><article><span>BPM ước lượng</span><strong>{result.bpm}</strong><small>{result.bpmConfidence}% tin cậy</small></article><article><span>Tâm âm</span><strong>{result.key}</strong><small>{result.keyConfidence}% tin cậy</small></article><article><span>Hoạt động</span><strong>{result.activityPercent}%</strong><small>Nghỉ ước lượng {result.restPercent}%</small></article></div><h2>Waveform &amp; hoạt động</h2><svg viewBox="0 0 900 150" className="audio-wave" aria-label="Dạng sóng audio">{result.waveform.map((value, index) => <line key={index} x1={index * 5} x2={index * 5} y1={75-value*65} y2={75+value*65} />)}</svg><div className="activity-sections"><b>Đoạn hoạt động cao:</b>{result.highActivitySections.length ? result.highActivitySections.map(section => <span key={section.time}>{time(section.time)}</span>) : <span>Không phát hiện đoạn nổi bật</span>}</div></section>; }
function MidiSection({ report, metrics, tracks, melodyTrack, leftTrack, setMelodyTrack, setLeftTrack, position, audioDuration, seek }: { report: PianoReport; metrics: MidiPerformanceMetrics; tracks: number[]; melodyTrack: number; leftTrack: number; setMelodyTrack: (track: number) => void; setLeftTrack: (track: number) => void; position: number; audioDuration: number; seek: (time: number) => void }) {
  const melody = useMemo(() => extractTopMelody(report.notes.filter(note => note.track === melodyTrack)), [report, melodyTrack]);
  const rollNotes = useMemo(() => report.notes.map((note,index)=><rect key={index} x={note.start/report.duration*1000} y={(108-note.note)*3} width={Math.max(2,note.duration/report.duration*1000)} height="5" />), [report]);
  const contourPoints = useMemo(() => melody.map(note=>`${note.start/report.duration*1000},${170-(note.note-21)/87*150}`).join(" "), [melody, report.duration]);
  const reportPosition = mapPlaybackPosition(position, audioDuration, report.duration);
  const activeNotes = report.notes.map((note,index) => ({ note, index })).filter(({note}) => reportPosition >= note.start && reportPosition < note.start + note.duration);
  const seekReportTime = (reportTime: number) => seek(mapPlaybackPosition(reportTime, report.duration, audioDuration));
  const clickTime = (event: React.MouseEvent<SVGSVGElement>) => seek((event.clientX - event.currentTarget.getBoundingClientRect().left) / event.currentTarget.getBoundingClientRect().width * audioDuration);
  return <><section className="track-select"><h2>Vai trò track MIDI</h2><small>Playhead căn theo % thời lượng Audio ↔ MIDI.</small><label>Giai điệu<select value={melodyTrack} onChange={event => setMelodyTrack(Number(event.target.value))}>{tracks.map(track => <option key={track} value={track}>Track {track + 1}</option>)}</select></label><label>Tay trái<select value={leftTrack} onChange={event => setLeftTrack(Number(event.target.value))}>{tracks.map(track => <option key={track} value={track}>Track {track + 1}</option>)}</select></label></section><section className="midi-metrics">{metricCards(metrics)}</section><section className="piano-viz"><header><h2>Piano roll &amp; contour giai điệu</h2><span>Nhấp để chuyển vị trí phát</span></header><svg className="piano-roll synced-viz" viewBox="0 0 1000 260" onClick={clickTime}>{rollNotes}{activeNotes.map(({note,index})=><rect className="active-note" key={`active-${index}`} x={note.start/report.duration*1000} y={(108-note.note)*3} width={Math.max(2,note.duration/report.duration*1000)} height="5" />)}<line className="midi-playhead" x1={reportPosition/report.duration*1000} x2={reportPosition/report.duration*1000} y1="0" y2="260" /></svg><svg className="contour synced-viz" viewBox="0 0 1000 190" onClick={clickTime}><polyline points={contourPoints} /><line className="midi-playhead" x1={reportPosition/report.duration*1000} x2={reportPosition/report.duration*1000} y1="0" y2="190" /></svg></section><ChordTimeline report={report} position={reportPosition} seek={seekReportTime} />{metrics.denseSections.length > 0 && <section className="dense-list"><h2>Đoạn dày bất thường</h2>{metrics.denseSections.map(section=><button key={section.start} onClick={() => seekReportTime(section.start)}>{time(section.start)} · {section.notesPerMinute} nốt/phút</button>)}</section>}</>;
}
function ChordTimeline({ report, position, seek }: { report: PianoReport; position: number; seek: (time: number) => void }) {
  const activeIndex = report.chords.findIndex(chord => position >= chord.start && position < chord.end); const active = useRef<HTMLButtonElement>(null);
  useEffect(() => { active.current?.scrollIntoView({ behavior: "smooth", block: "nearest", inline: "center" }); }, [activeIndex]);
  return <section className="piano-chords"><header><h2>Hợp âm</h2><b>{report.progression || "Không phát hiện tiến trình ổn định"}</b></header><div className="chord-scroll">{report.chords.map((chord,index)=><button ref={index === activeIndex ? active : undefined} className={index === activeIndex ? "active-chord" : ""} key={index} style={{flex:chord.end-chord.start}} onClick={() => seek(chord.start)}><strong>{chord.name}</strong><small>{chord.roman} · {time(chord.start)}</small></button>)}<i className="chord-playhead" style={{ left: `${Math.max(0, Math.min(100, position / report.duration * 100))}%` }} /></div></section>;
}
function metricCards(m: MidiPerformanceMetrics) { const values = [["Nốt giai điệu/phút",m.notesPerMinute],["Thời gian nghỉ",`${m.restPercent}%`],["Quãng TB",`${m.averageInterval} st`],["Nhảy >5 / >7",`${m.leapsOver5} / ${m.leapsOver7}`],["Range giai điệu",`${m.range} st`],["Đổi hợp âm/phút",m.chordChangesPerMinute],["Nốt tay trái/hợp âm",m.leftNotesPerChord],["Lặp motif",m.motifRepetitions],["Độ dài câu TB",`${m.averagePhraseLength}s`]]; return values.map(([label,value])=><article key={label}><span>{label}</span><strong>{value}</strong></article>); }
function Comparison({ demo, reference }: { demo: MidiPerformanceMetrics; reference: MidiPerformanceMetrics }) { const rows: Array<[string,keyof MidiPerformanceMetrics]> = [["Nốt/phút","notesPerMinute"],["Thời gian nghỉ %","restPercent"],["Quãng TB","averageInterval"],["Nhảy >7","leapsOver7"],["Range","range"],["Đổi hợp âm/phút","chordChangesPerMinute"],["Nốt tay trái/hợp âm","leftNotesPerChord"],["Lặp motif","motifRepetitions"],["Độ dài câu TB","averagePhraseLength"]]; return <section className="midi-comparison"><h2>So sánh MIDI trực tiếp</h2><table><thead><tr><th>Chỉ số</th><th>Demo</th><th>Reference</th></tr></thead><tbody>{rows.map(([label,key])=><tr key={label}><td>{label}</td><td>{String(demo[key])}</td><td>{String(reference[key])}</td></tr>)}</tbody></table></section>; }
function ProfileEvaluationPanel({ profile, evaluation, onSeek }: { profile: ReferenceLibraryProfile; evaluation: ProfileEvaluation; onSeek: (time:number)=>void }) { const status = { within: "Trong vùng", below: "Thấp", above: "Cao" }; const health = assessReferenceProfile(profile); const hasMetrics = evaluation.metrics.length > 0; return <section className="profile-evaluation"><header><div><p className="eyebrow">DEMO VS HỒ SƠ {profile.tracks.length} BÀI</p><h2>{profile.name}</h2><p>Vùng thường gặp = khoảng tứ phân vị 25–75% của thư viện. Đây là độ phù hợp, không phải điểm chất lượng.</p></div><strong>{hasMetrics ? evaluation.fitScore : "—"}<small>/100<br/>PHÙ HỢP HỒ SƠ</small></strong></header>{health.status === "limited" && <p className="reference-message">Kết quả giới hạn: chỉ {health.verifiedTempoCount}/{health.trackCount} bài có BPM đủ tin cậy và {health.transcriptionCount}/{health.trackCount} bài có AI chép nốt. Các chỉ số thiếu mẫu đã tự động bị loại khỏi điểm.</p>}<div className="profile-evaluation-meta"><span>AI top-voice phủ {evaluation.transcriptionCoverage}% thư viện</span><span>BPM tin cậy {health.verifiedTempoCount}/{health.trackCount} bài</span><span>{evaluation.metrics.filter(metric=>metric.status==="within").length}/{evaluation.metrics.length} chỉ số trong vùng</span></div><div className="profile-metric-grid">{evaluation.metrics.map(metric=><article className={metric.status} key={metric.key}><span>{metric.label}</span><strong>{metric.value} {metric.unit}</strong><small>{status[metric.status]} · vùng {metric.stats.q25}–{metric.stats.q75} · n={metric.stats.sampleSize}</small></article>)}</div><h3>Đoạn cần nghe lại trước</h3>{!hasMetrics ? <p className="reference-message">Chưa có đủ chỉ số cùng loại để tính độ phù hợp. Hãy bổ sung hoặc xác nhận dữ liệu trong hồ sơ.</p> : evaluation.findings.length ? evaluation.findings.slice(0,7).map(finding=><button className="profile-finding" key={finding.id} onClick={()=>finding.start!==undefined&&onSeek(finding.start)} disabled={finding.start===undefined}><b>#{finding.rank}</b><span>{finding.textVi}</span>{finding.start!==undefined&&<em>Nghe đoạn</em>}</button>) : <p className="profile-all-clear">Các đặc trưng đủ mẫu đang nằm trong vùng thường gặp của hồ sơ. Vẫn cần chấm checklist bằng tai.</p>}</section>; }
function AiTranscriptionSection({ transcription, position, audioDuration, seek }: { transcription: PianoTranscription; position:number; audioDuration:number; seek:(time:number)=>void }) {
  const values: Array<[string,string|number]> = [["Nốt top-voice/phút",transcription.melodyNotesPerMinute],["Khoảng nghỉ top-voice",`${transcription.melodyRestPercent}%`],["Quãng đi trung bình",`${transcription.averageInterval} st`],["Nhảy >7/phút",transcription.largeLeapsPerMinute],["Âm vực top-voice",`${transcription.melodyRange} st`],["Nốt âm khu thấp/phút",transcription.lowNotesPerMinute],["Tái diễn mô-típ",`${transcription.motifRecurrence}%`],["Độ dài câu TB",`${transcription.averagePhraseLength}s`],["Độ tin cậy heuristic",`${transcription.confidencePercent}%`]];
  const transcriptionPosition=mapPlaybackPosition(position,audioDuration,transcription.duration);
  const click=(event:React.MouseEvent<SVGSVGElement>)=>seek(mapPlaybackPosition((event.clientX-event.currentTarget.getBoundingClientRect().left)/event.currentTarget.getBoundingClientRect().width*transcription.duration,transcription.duration,audioDuration));
  const noteLayer=useMemo(()=>{const minPitch=Math.min(36,...transcription.notes.map(note=>note.pitch));const maxPitch=Math.max(84,...transcription.notes.map(note=>note.pitch));const range=Math.max(1,maxPitch-minPitch);const melody=new Set(transcription.melodyNotes);return transcription.notes.map((note,index)=><rect className={melody.has(note)?"estimated-melody":""} key={index} x={note.start/transcription.duration*1000} y={(maxPitch-note.pitch)/range*205} width={Math.max(2,note.duration/transcription.duration*1000)} height="5"/>);},[transcription]);
  return <section className="ai-transcription"><header><div><p className="eyebrow">AI AUDIO-TO-NOTE · ƯỚC LƯỢNG</p><h2>Top-voice và khoảng nghỉ từ audio</h2></div><span>Không thay thế MIDI sáng tác</span></header><div className="ai-metric-grid">{values.map(([label,value])=><article key={label}><span>{label}</span><strong>{value}</strong></article>)}</div><svg className="ai-piano-roll synced-viz" viewBox="0 0 1000 220" onClick={click} aria-label="Piano roll ước lượng từ audio">{noteLayer}<line className="midi-playhead" x1={transcriptionPosition/transcription.duration*1000} x2={transcriptionPosition/transcription.duration*1000} y1="0" y2="220"/></svg><p>Top-voice là nốt cao nhất trong mỗi nhóm onset gần nhau. “Nốt âm khu thấp” không đồng nghĩa chắc chắn với tay trái. Nhấp piano roll để nghe tại vị trí tương ứng.</p></section>;
}
function AiTranscriptionComparison({ demo, reference }: { demo: PianoTranscription; reference: PianoTranscription }) { const rows: Array<[string,number,number,string]> = [["Nốt top-voice/phút",demo.melodyNotesPerMinute,reference.melodyNotesPerMinute,"/phút"],["Khoảng nghỉ top-voice",demo.melodyRestPercent,reference.melodyRestPercent,"%"],["Quãng đi trung bình",demo.averageInterval,reference.averageInterval,"st"],["Nhảy >7 bán âm/phút",demo.largeLeapsPerMinute,reference.largeLeapsPerMinute,"/phút"],["Âm vực top-voice",demo.melodyRange,reference.melodyRange,"st"],["Nốt âm khu thấp/phút",demo.lowNotesPerMinute,reference.lowNotesPerMinute,"/phút"],["Tái diễn mô-típ",demo.motifRecurrence,reference.motifRecurrence,"%"],["Độ dài câu top-voice",demo.averagePhraseLength,reference.averagePhraseLength,"s"]]; return <section className="midi-comparison audio-note-comparison"><p className="eyebrow">BASIC PITCH · SO SÁNH ƯỚC LƯỢNG</p><h2>Top-voice Demo vs Reference</h2><p>Hai bên được chép nốt bằng cùng một mô hình để hỗ trợ nghe A/B. Sai số nhận nốt có thể khác nhau giữa hai bản audio.</p><table><thead><tr><th>Chỉ số</th><th>Demo</th><th>Reference</th></tr></thead><tbody>{rows.map(([label,demoValue,referenceValue,unit])=><tr key={label}><td>{label}</td><td>{demoValue} {unit}</td><td>{referenceValue} {unit}</td></tr>)}</tbody></table></section>; }
function CompositionOverview({ title, result, confirmedBpm, onConfirmedBpm }: { title: string; result: CompositionAnalysis; confirmedBpm:number; onConfirmedBpm:(bpm:number)=>void }) {
  const cards: Array<[string,string, keyof CompositionAnalysis["confidence"]]> = [["Độ ổn định tempo",`${result.tempoStability}%`,"tempo"],["Rubato",`${result.rubato}%`,"rubato"],["Pitch class nổi trội",result.tonalCenter,"tonalCenter"],["Mật độ tiếng đàn",`${result.onsetDensity}/phút`,"onsets"],["Khoảng nghỉ audio",`${result.restPercent}% · dài nhất ${result.longestRest}s`,"phrasing"],["Độ dài câu ước lượng",`${result.averagePhraseLength}s`,"phrasing"],["Intro / outro",`${result.introSilence}s / ${result.outroSilence}s`,"sections"],["Lặp mẫu nhịp onset",`${result.repetition}%`,"repetition"],["Biến động onset/năng lượng",String(result.melodicMovement),"melodicMovement"],["Biến đổi màu âm",`${result.harmonicChangeRate}/phút`,"harmonicChange"],["Hoạt động",`${result.activityPercent}%`,"sections"]];
  const tempo = result.tempoCrossCheck;
  const statusLabels = { agreement: "Đồng thuận", "half-double": "Nửa / gấp đôi", conflict: "Cần xác nhận", "zirect-only": "Chỉ Zirect", "essentia-only": "Chỉ Essentia", unavailable: "Không xác định" };
  const zirectCandidates = tempo?.zirect.candidates ?? result.tempoCandidates;
  const essentiaConfidence = typeof tempo?.essentia?.confidence === "number" ? `Confidence thô: ${tempo.essentia.confidence}` : (tempo?.essentia?.algorithm ?? "PercivalBpmEstimator");
  return <section className="composition-overview"><header><div><p className="eyebrow">AUDIO ESTIMATES</p><h2>{title}</h2></div><span>Ước lượng sáng tác · không đánh giá mix/master</span></header>
    <div className={`tempo-review ${tempo?.needsConfirmation ? "needs-confirmation" : ""}`}>
      <div className="tempo-source-grid">
        <article><span>Bộ đo Zirect</span><strong>{tempo?.zirect.bpm || result.bpm || "—"}</strong><small>Confidence: {tempo?.zirect.confidence ?? result.confidence.tempo}</small></article>
        <article><span>Essentia.js</span><strong>{tempo?.essentia?.bpm || "—"}</strong><small>{tempo?.essentia ? essentiaConfidence : "Fallback vẫn hoạt động"}</small></article>
        <article className={`tempo-consensus ${tempo?.status ?? "zirect-only"}`}><span>BPM đề xuất</span><strong>{tempo?.recommendedBpm || result.bpm || "—"}</strong><small>{tempo ? statusLabels[tempo.status] : "Bộ đo Zirect"}</small></article>
      </div>
      <label>BPM dùng để đánh giá<input type="number" min="30" max="200" value={confirmedBpm||""} onChange={event=>{const bpm=Number(event.target.value);if(bpm>=30&&bpm<=200)onConfirmedBpm(bpm)}} /><small>Giá trị ban đầu là đề xuất tự động; sửa trường này để xác nhận bằng tai.</small></label>
      <div className="tempo-candidates"><p><b>Zirect:</b> {zirectCandidates.length?zirectCandidates.map(candidate=>`${candidate.bpm} BPM · ${candidate.score}%`).join(" · "):"Không đủ dữ liệu"}</p><p><b>Essentia:</b> {tempo?.essentia?.candidates.length?tempo.essentia.candidates.map(bpm=>`${bpm} BPM`).join(" · "):"Không có ứng viên"}</p></div>
      <em>{tempo?.message ?? (result.tempoAmbiguous ? "Có thể nhầm nhịp gấp đôi hoặc nửa nhịp — nên xác nhận bằng tai." : "Đang dùng kết quả từ bộ đo Zirect.")}</em>
    </div>
    <div className="estimate-grid">{cards.map(([label,value,key])=><article key={label}><span>{label}</span><strong>{value}</strong><small>Confidence: {result.confidence[key]}</small></article>)}</div><div className="structure-sections"><b>Các đoạn hoạt động và cấu trúc</b>{result.sections.map((section,index)=><span key={section.start}>{index+1} · {time(section.start)}–{time(section.end)} · {section.activity}%</span>)}</div><p className="estimate-note">Các số liệu audio là proxy từ năng lượng, onset và thay đổi màu phổ. “Pitch class nổi trội” không khẳng định giọng; “biến đổi màu âm” không khẳng định hợp âm.</p></section>;
}
function AudioComparison({ comparison, seek }: { comparison: CompositionComparison; seek: (time:number,length:number)=>void }) { return <section className="audio-comparison"><header><div><p className="eyebrow">DEMO VS REFERENCE</p><h2>So sánh theo đoạn chuẩn hoá</h2></div><span>Căn theo % thời lượng</span></header><table><thead><tr><th>Chỉ số</th><th>Demo</th><th>Reference</th></tr></thead><tbody>{comparison.rows.map(r=><tr key={r.label}><td>{r.label}</td><td>{r.demo} {r.unit}</td><td>{r.reference} {r.unit}</td></tr>)}</tbody></table><h3>Khác biệt lớn nhất</h3>{comparison.findings.slice(0,5).map(f=><button className="comparison-finding" key={f.id} onClick={()=>seek(f.demoStart,10)}><b>#{f.rank}</b><span>{f.textVi}</span></button>)}</section>; }
function Waveform({ label, result, normalizedPosition, active, loopStart, loopSpan, markers, onSeek }: { label:string; result:CompositionAnalysis; normalizedPosition:number; active:boolean; loopStart:number; loopSpan:number; markers:Marker[]; onSeek:(normalized:number)=>void }) { const normalized=Math.max(0,Math.min(1,normalizedPosition)); return <div className={`dual-wave ${active?"current":""}`}><header><b>{label}</b><span>{active?"Nguồn hiện tại":"Căn chỉnh chuẩn hoá"} · {time(normalized*result.duration)}</span></header><svg viewBox="0 0 900 120" onClick={e=>onSeek((e.clientX-e.currentTarget.getBoundingClientRect().left)/e.currentTarget.getBoundingClientRect().width)} aria-label={`Waveform ${label}`}><rect className="wave-bg" width="900" height="120"/>{loopSpan>0&&<rect className="loop-region" x={loopStart*900} width={Math.min(loopSpan,1-loopStart)*900} height="120"/>}{result.waveform.map((v,i)=><line key={i} x1={i*5} x2={i*5} y1={60-v*52} y2={60+v*52}/>) }{markers.map(m=><line className="wave-marker" key={m.id} x1={m.time/result.duration*900} x2={m.time/result.duration*900} y1="0" y2="120"/>)}<line className="wave-playhead" x1={normalized*900} x2={normalized*900} y1="0" y2="120"/></svg></div>; }
function ABPlayer({ demoUrl, referenceUrl, demoAnalysis, referenceAnalysis, comparison, markers, setMarkers, audio, position, setPosition: setDemoPosition, setDuration: setDemoDuration, seekRequest }: { demoUrl:string; referenceUrl:string; demoAnalysis:CompositionAnalysis; referenceAnalysis?:CompositionAnalysis; comparison?:CompositionComparison; markers: Marker[]; setMarkers: (markers: Marker[]) => void; audio: React.RefObject<HTMLAudioElement | null>; position: number; setPosition: (time: number) => void; setDuration: (duration: number) => void; seekRequest?: { id: number; demoTime: number } }) {
  const [source,setSource]=useState<"demo"|"reference">("demo"),[blind,setBlind]=useState(false),[loopSeconds,setLoopSeconds]=useState(0),[loopStart,setLoopStart]=useState(0),[loopSpan,setLoopSpan]=useState(0),[playing,setPlaying]=useState(false),[composer,setComposer]=useState(false),[manual,setManual]=useState(""),[markerText,setMarkerText]=useState(""),[markerError,setMarkerError]=useState(""),[editing,setEditing]=useState<string>(),[playbackPosition,setPlaybackPosition]=useState(0),[playbackDuration,setPlaybackDuration]=useState(demoAnalysis.duration); const textarea=useRef<HTMLTextAreaElement>(null); const pendingPosition=useRef<number | undefined>(undefined); const pendingResume=useRef(false); const lastVisualUpdate=useRef(0); const playbackDurationRef=useRef(demoAnalysis.duration); const demoDurationRef=useRef(demoAnalysis.duration);
  useEffect(()=>{if(composer)setTimeout(()=>textarea.current?.focus(),0)},[composer]);
  const currentDuration=Math.max(.01,playbackDuration); const normalizedPosition=mapPlaybackPosition(playbackPosition,currentDuration,1);
  const setPosition=(raw:number)=>{setPlaybackPosition(raw);setDemoPosition(mapPlaybackPosition(raw,playbackDurationRef.current,demoDurationRef.current))}; const setDuration=(duration:number)=>{if(!Number.isFinite(duration)||duration<=0)return;playbackDurationRef.current=duration;setPlaybackDuration(duration);if(source==="demo"){demoDurationRef.current=duration;setDemoDuration(duration)}};
  const switchTo=(next:"demo"|"reference", normalized=normalizedPosition, forcePlay=false)=>{if(next==="reference"&&!referenceUrl)return;const target=Math.max(0,Math.min(1,normalized));const resume=forcePlay||!audio.current?.paused;if(next===source&&audio.current){audio.current.currentTime=target*(audio.current.duration||currentDuration);setPosition(audio.current.currentTime);if(resume)void audio.current.play();return}const estimatedDuration=next==="demo"?demoDurationRef.current:referenceAnalysis?.duration??demoAnalysis.duration;playbackDurationRef.current=estimatedDuration;setPlaybackDuration(estimatedDuration);pendingPosition.current=target;pendingResume.current=resume;setSource(next)};
  useEffect(()=>{if(seekRequest)switchTo("demo",mapPlaybackPosition(seekRequest.demoTime,demoDurationRef.current,1))},[seekRequest?.id]); useEffect(()=>{if(!playing)return;let frame=0;const update=(timestamp:number)=>{if(audio.current&&timestamp-lastVisualUpdate.current>=50){lastVisualUpdate.current=timestamp;setPosition(audio.current.currentTime)}frame=requestAnimationFrame(update)};frame=requestAnimationFrame(update);return()=>cancelAnimationFrame(frame)},[playing,audio,setDemoPosition,demoAnalysis.duration,source,referenceAnalysis?.duration]);
  const demoPosition=position; const openComposer=(marker?:Marker)=>{setEditing(marker?.id);setManual(time(marker?.time??demoPosition));setMarkerText(marker?.text??"");setMarkerError("");setComposer(true)}; const cancel=()=>{setComposer(false);setEditing(undefined);setMarkerError("")}; const saveMarker=()=>{const parsed=parseMarkerTimestamp(manual,demoPosition,demoAnalysis.duration);if(parsed.error){setMarkerError(parsed.error);return}if(!markerText.trim()){setMarkerError("Hãy nhập feedback cho đánh dấu.");return}const marker={id:editing??crypto.randomUUID(),time:parsed.time!,text:markerText.trim()};setMarkers([...markers.filter(m=>m.id!==editing),marker].sort((a,b)=>a.time-b.time));cancel()}; const startFinding=(start:number,length:number)=>{const normalized=start/demoAnalysis.duration;setLoopSeconds(length);setLoopStart(normalized);setLoopSpan(Math.min(1-normalized,length/demoAnalysis.duration));switchTo("demo",normalized,true)};
  const toggleLoop=(seconds:number)=>{if(loopSeconds===seconds){setLoopSeconds(0);setLoopSpan(0);return}setLoopSeconds(seconds);setLoopStart(normalizedPosition);setLoopSpan(Math.min(1-normalizedPosition,seconds/Math.max(.01,currentDuration)))};
  return <section className="ab-workflow"><header><div><h2>Dual A/B waveform</h2><p>Playhead và loop căn theo % thời lượng khi đổi nguồn</p></div><label><input type="checkbox" checked={blind} onChange={e=>setBlind(e.target.checked)}/> Blind A/B</label></header><Waveform label={blind?"A":"Demo"} result={demoAnalysis} active={source==="demo"} normalizedPosition={normalizedPosition} loopStart={loopStart} loopSpan={loopSpan} markers={markers} onSeek={n=>switchTo("demo",n)}/>{referenceAnalysis&&<Waveform label={blind?"B":"Reference"} result={referenceAnalysis} active={source==="reference"} normalizedPosition={normalizedPosition} loopStart={loopStart} loopSpan={loopSpan} markers={[]} onSeek={n=>switchTo("reference",n)}/>}<audio ref={audio} src={source==="demo"?demoUrl:referenceUrl} controls onPlay={()=>setPlaying(true)} onPause={()=>setPlaying(false)} onLoadedMetadata={e=>{const element=e.currentTarget;setDuration(element.duration);const normalized=pendingPosition.current;if(normalized!==undefined){element.currentTime=normalized*element.duration;setPosition(element.currentTime);pendingPosition.current=undefined}if(pendingResume.current){pendingResume.current=false;void element.play()}}} onTimeUpdate={e=>{const element=e.currentTarget;if(!playing)setPosition(element.currentTime);const normalized=element.currentTime/Math.max(.01,element.duration);if(loopSpan&&normalized>=loopStart+loopSpan){element.currentTime=loopStart*element.duration;void element.play()}}}/><div className="ab-controls"><button className={source==="demo"?"active":""} onClick={()=>switchTo("demo")}>{blind?"A":"Demo"}</button><button className={source==="reference"?"active":""} disabled={!referenceUrl} onClick={()=>switchTo("reference")}>{blind?"B":"Reference"}</button>{[5,10,15].map(n=><button className={loopSeconds===n?"active":""} key={n} onClick={()=>toggleLoop(n)}>Loop {n}s</button>)}{[.75,1].map(n=><button key={n} onClick={()=>{if(audio.current)audio.current.playbackRate=n}}>{n}x</button>)}</div>{comparison&&<div className="finding-loops">{comparison.findings.slice(0,5).map(f=><div key={f.id}><button onClick={()=>startFinding(f.demoStart,10)}>#{f.rank} {f.textVi}</button>{[5,10,15].map(n=><button key={n} onClick={()=>startFinding(f.demoStart,n)}>{n}s</button>)}</div>)}</div>}<div className="marker-composer"><button className="marker-trigger" onClick={()=>openComposer()}>+ Đánh dấu timestamp</button>{composer&&<div className="marker-form"><label>Timestamp<input value={manual} onChange={e=>setManual(e.target.value)} aria-label="Timestamp mm:ss"/></label><label>Feedback<textarea ref={textarea} value={markerText} onChange={e=>setMarkerText(e.target.value)} placeholder="Nhập nhận xét tự do…"/></label>{markerError&&<p role="alert">{markerError}</p>}<div><button onClick={saveMarker}>Lưu đánh dấu</button><button onClick={cancel}>Huỷ</button></div></div>}</div><div className="marker-list">{markers.map(marker=><div key={marker.id}><button onClick={()=>switchTo("demo",marker.time/demoAnalysis.duration,true)}><b>{time(marker.time)}</b>{marker.text}</button><button onClick={()=>openComposer(marker)}>Sửa</button><button aria-label={`Xoá marker ${time(marker.time)}`} onClick={()=>setMarkers(markers.filter(m=>m.id!==marker.id))}>×</button></div>)}</div></section>;
}
function FeedbackEditor({ language, value, setValue }: { language: string; value: string; setValue: (value: string) => void }) { const [copyStatus,setCopyStatus]=useState<""|"copied"|"error">(""); const copy=async()=>{try{await copyPianoFeedback(value);setCopyStatus("copied");window.setTimeout(()=>setCopyStatus(""),1800)}catch{setCopyStatus("error")}}; return <section className="feedback-editor"><header><h2>Feedback · {language}</h2><button onClick={copy}>{copyStatus==="copied"?"Đã sao chép ✓":copyStatus==="error"?"Không sao chép được":"Sao chép"}</button></header><textarea value={value} onChange={event=>setValue(event.target.value)} /></section>; }
function feedback(language: "vi"|"en", metrics?: MidiPerformanceMetrics, comparison?: CompositionComparison, confirmedBpm?:number, profileEvaluation?:ProfileEvaluation, markers: Marker[] = [], scores: Array<number | null> = []) {
  const labels = language === "vi" ? CHECKS : CHECKS_EN;
  const completed = scores.length === CHECKS.length && scores.every((score): score is number => score !== null);
  const total = completed ? scores.reduce((sum, score) => sum + score!, 0) : undefined;
  const strengths = scores.map((score, index) => ({ score, label: labels[index] })).filter(item => item.score !== null && item.score >= 4).map(item => item.label);
  const weakChecks = scores.map((score, index) => ({ score, label: labels[index] })).filter(item => item.score !== null && item.score <= 2).map(item => item.label);
  const profileNotes = profileEvaluation?.findings.slice(0, 2).map(finding => language === "vi" ? finding.textVi : finding.textEn) ?? [];
  const comparisonNotes = comparison?.findings.slice(0, 2).map(finding => language === "vi" ? finding.textVi : finding.textEn) ?? [];
  const dense = metrics?.denseSections[0];
  const technicalNotes = profileNotes.length ? profileNotes : comparisonNotes.length ? comparisonNotes : dense ? [`${time(dense.start)}: ${language === "vi" ? "kiểm tra mật độ giai điệu" : "review melodic density"}.`] : [];
  const markerLines = markers.map(marker => `${time(marker.time)} — ${marker.text}`);
  const priorities = [...markerLines, ...weakChecks.map(label => language === "vi" ? `Checklist thấp: ${label}.` : `Low checklist score: ${label}.`), ...technicalNotes].slice(0, 6);
  const conclusion = !completed
    ? (language === "vi" ? "Chưa kết luận — hãy hoàn tất checklist A&R và nghe lại các timestamp quan trọng." : "No decision yet — complete the A&R checklist and review the important timestamps.")
    : total! >= 28
      ? (language === "vi" ? "Có thể tiếp tục quy trình, sau khi xác nhận các ghi chú còn lại bằng tai." : "Ready to continue after the remaining notes are confirmed by ear.")
      : total! >= 21
        ? (language === "vi" ? "Cần chỉnh sửa có mục tiêu trước khi duyệt." : "Targeted revision is needed before approval.")
        : (language === "vi" ? "Cần chỉnh sửa đáng kể về giai điệu hoặc cấu trúc." : "Substantial melodic or structural revision is needed.");
  const evidence = profileEvaluation?.metrics.length
    ? (language === "vi" ? `Độ phù hợp hồ sơ: ${profileEvaluation.fitScore}/100, dựa trên ${profileEvaluation.metrics.length} chỉ số đủ mẫu; đây không phải điểm chất lượng.` : `Profile fit: ${profileEvaluation.fitScore}/100 across ${profileEvaluation.metrics.length} sufficiently sampled metrics; this is not a quality score.`)
    : profileEvaluation
      ? (language === "vi" ? "Hồ sơ chưa có đủ chỉ số cùng loại để tính độ phù hợp." : "The profile does not yet contain enough comparable metrics to calculate fit.")
    : metrics
      ? (language === "vi" ? `${metrics.notesPerMinute} nốt/phút; ${metrics.restPercent}% thời gian nghỉ.` : `${metrics.notesPerMinute} notes/minute; ${metrics.restPercent}% rest time.`)
      : (language === "vi" ? "Chỉ có audio; dữ liệu nốt nếu xuất hiện là ước lượng AI, không phải MIDI chính xác." : "Audio only; any note data is AI-estimated rather than exact MIDI.");
  const bullet = (items: string[], empty: string) => items.length ? items.map(item => `- ${item}`).join("\n") : `- ${empty}`;
  if (language === "vi") return `KẾT LUẬN\n${conclusion}${total === undefined ? "" : ` (${total}/35)`}\n\nĐIỂM MẠNH\n${bullet(strengths, "Chưa có tiêu chí nào được chấm từ 4–5.")}\n\nƯU TIÊN SỬA + TIMESTAMP\n${bullet(priorities, "Chưa có ưu tiên; hãy thêm marker và chấm checklist.")}\n\nBẰNG CHỨNG\n- BPM đã xác nhận bằng tai: ${confirmedBpm ?? "chưa xác nhận"}.\n- ${evidence}\n\nMỤC TIÊU CHO PHIÊN BẢN TIẾP THEO\nXử lý các ưu tiên trên nhưng giữ lại những tiêu chí đã được chấm tốt.`;
  return `CONCLUSION\n${conclusion}${total === undefined ? "" : ` (${total}/35)`}\n\nSTRENGTHS\n${bullet(strengths, "No criterion has yet received a 4–5 score.")}\n\nPRIORITY FIXES + TIMESTAMPS\n${bullet(priorities, "No priority yet; add markers and complete the checklist.")}\n\nEVIDENCE\n- BPM confirmed by ear: ${confirmedBpm ?? "not confirmed"}.\n- ${evidence}\n\nGOAL FOR THE NEXT VERSION\nAddress the priorities above while preserving the criteria that scored well.`;
}
